(83, 'TKT-2026-0067', 12, 10, 5, NULL, 'Official transcript request delayed beyond 10 days', 'I requested an official transcript for a job application over 10 working days ago and it still has not been issued.', 'NEW', 'HIGH', 0, NULL, NULL, '2026-08-22T09:00:00', '2026-08-15T09:00:00', '2026-09-17T10:31:29.4696549', NULL, NULL, NULL, NULL, '2026-09-18T11:15:17.3166999'),
(84, 'TKT-2026-0068', 13, 10, 5, NULL, 'Visa confirmation letter needed urgently for embassy', 'I need an official student status and visa confirmation letter for an upcoming embassy appointment next week.', 'ASSIGNED', 'URGENT', 0, NULL, NULL, '2026-08-19T09:00:00', '2026-08-18T09:00:00', '2026-08-19T09:00:00', NULL, NULL, NULL, NULL, '2026-09-18T11:15:17.3343844'),
(85, 'TKT-2026-0069', 8, 11, 6, 6, 'Eduroam Wi-Fi keeps disconnecting in the library', 'My laptop keeps losing the Eduroam Wi-Fi connection every few minutes while I am in the library, but it is stable elsewhere on campus.', 'IN_PROGRESS', 'HIGH', 0, NULL, NULL, '2026-08-24T09:00:00', '2026-08-21T09:00:00', '2026-09-17T10:31:29.4730968', NULL, NULL, NULL, NULL, '2026-09-18T11:15:17.3583278'),
(86, 'TKT-2026-0070', 9, 11, 6, 6, 'Cannot connect to campus Wi-Fi from new laptop', 'I recently switched from a laptop I bought while on exchange to a new one purchased locally, and cannot connect to the campus Wi-Fi network (UniDesk-Student) at our Colombo campus, even after re-entering my student credentials multiple times.', 'RESOLVED', 'HIGH', 0, NULL, NULL, '2026-08-25T09:00:00', '2026-08-24T09:00:00', '2026-08-26T09:00:00', '2026-08-26T09:00:00', NULL, NULL, NULL, NULL),
(87, 'TKT-2026-0071', 10, 12, 6, 6, 'Microsoft 365 license not activating on student account', 'My Microsoft 365 Education license shows as unlicensed when I try to activate Word and Excel using my student email account.', 'CLOSED', 'LOW', 0, NULL, NULL, '2026-09-04T09:00:00', '2026-08-28T09:00:00', '2026-09-17T11:49:24.0936636', '2026-08-30T09:00:00', NULL, NULL, NULL, NULL),
