(91, 'TKT-2026-0075', 14, 14, 7, NULL, 'IEEE Student Branch membership renewal query', 'I would like to renew my IEEE Student Branch membership but cannot find the renewal form on the student affairs page.', 'IN_PROGRESS', 'HIGH', 0, NULL, NULL, '2026-09-17T09:00:00', '2026-09-10T09:00:00', '2026-09-17T10:31:29.4730968', NULL, NULL, NULL, NULL, '2026-09-18T11:15:17.4246642'),
(92, 'TKT-2026-0076', 15, 14, 7, NULL, 'Requesting information about Rotaract club sign-up', 'Could someone point me to the sign-up process and meeting schedule for the campus Rotaract club for this semester?', 'RESOLVED', 'URGENT', 0, NULL, NULL, '2026-09-14T09:00:00', '2026-09-13T09:00:00', '2026-09-15T09:00:00', '2026-09-15T09:00:00', NULL, NULL, NULL, NULL),
