(104, 'TKT-2026-0078', 17, 2, 1, 5, 'Merit scholarship renewal not reflected in this semester''s fee invoice', 'I was awarded the 25% merit-based tuition waiver last semester after achieving a GPA above 3.70. This semester''s fee invoice generated on the portal shows the full tuition amount with no scholarship deduction applied. I have already made a partial payment based on the expected discounted amount via my Bank of Ceylon account and can share the deposit slip if needed. Could the Finance office please recheck my scholarship status and reissue a corrected invoice before the payment deadline on 30th September? My student ID is included in my profile.', 'IN_PROGRESS', 'NORMAL', 0, NULL, NULL, NULL, '2026-09-08T09:20:00', '2026-09-15T14:05:00', NULL, NULL, NULL, NULL, NULL),
(105, 'TKT-2026-0079', 20, 5, 3, 7, 'Re-sit exam fee payment confirmation not received for Database Systems module', 'I paid the repeat exam fee for Database Systems (which I failed last semester) via online banking on 3rd September, but I have not received the admission slip or index number for the re-sit. The exam timetable shows the paper is scheduled in about two weeks and I am worried I will not be allowed to sit it without the slip. Could someone confirm my payment has been received and issue the admission details as soon as possible?', 'RESOLVED', 'HIGH', 0, NULL, NULL, NULL, '2026-09-05T10:00:00', '2026-09-12T16:30:00', '2026-09-12T16:30:00', 'Payment of LKR 4,500 verified against the bank reconciliation report dated 4th September. Repeat exam admission slip has been generated and emailed to the student with index number RS/2026/0142. Student should bring the university ID card and this slip to the exam hall.', 7, '2026-09-12T16:30:00', NULL),
(106, 'TKT-2026-0080', 21, 11, 6, 6, 'Eduroam keeps disconnecting in the Engineering Faculty library annex', 'For the past few days my laptop keeps losing the Eduroam connection every 5-10 minutes while I am in the library annex next to the Engineering Faculty. It reconnects on its own but drops any in-progress upload, and yesterday it disrupted an online quiz submission on the LMS. Other students on the same floor mentioned the same issue. Could someone check the access point coverage in that area?', 'ASSIGNED', 'NORMAL', 0, NULL, NULL, NULL, '2026-09-16T15:40:00', '2026-09-17T09:10:00', NULL, NULL, NULL, NULL, NULL);
