INSERT INTO welfare_cases ([id], [reference_no], [student_id], [assigned_to], [subject], [description], [status], [is_urgent], [created_at], [updated_at], [resolved_at]) VALUES
(1, 'WEL-2026-0001', 11, 4, 'Emergency financial grant inquiry due to family medical crisis in Kandy', 'My father was admitted to Kandy General Hospital with sudden medical complications. Requesting temporary emergency financial relief grant to cover living costs this month.', 'IN_PROGRESS', 1, '2026-08-07T02:30:45.2167869', '2026-08-12T02:30:45.2167869', NULL),
(2, 'WEL-2026-0002', 12, 4, 'Academic stress and confidential mental health counseling consultation', 'Experiencing severe anxiety and insomnia due to final year capstone workload. Requesting appointment with university counseling psychologist.', 'RESOLVED', 0, '2026-08-10T02:30:45.2167869', '2026-08-14T02:30:45.2167869', '2026-08-14T02:30:45.2167869'),
(3, 'WEL-2026-0003', 8, 4, 'Hostel accommodation fee concession request for low-income background', 'Family income from agriculture in Polonnaruwa affected by drought. Seeking installment scheme or partial fee subsidy for university student hostel.', 'CLOSED', 0, '2026-08-12T02:30:45.2167869', '2026-08-17T02:30:45.2167869', '2026-08-17T02:30:45.2167869'),
(4, 'WEL-2026-0004', 9, 4, 'Special examination sitting arrangement for chronic health condition', 'Diagnosed with rheumatoid condition requiring ergonomic chair and 15-minute rest breaks during 3-hour written examination papers. Asiri Hospital medical certificate attached.', 'IN_PROGRESS', 1, '2026-08-15T02:30:45.2167869', '2026-08-22T02:30:45.2167869', NULL),
(5, 'WEL-2026-0005', 10, 4, 'Student hardship fund application for final semester laptop hardware assistance', 'My laptop motherboard failed during deep learning module. Applied for university student welfare loaner laptop for semester project.', 'RESOLVED', 0, '2026-08-17T02:30:45.2167869', '2026-08-21T02:30:45.2167869', '2026-08-21T02:30:45.2167869'),
(6, 'WEL-2026-0006', 13, NULL, 'Personal counseling & peer mentoring guidance request', 'Facing difficulty balancing part-time employment hours with academic study schedule. Looking for academic counselor guidance.', 'NEW', 0, '2026-08-20T02:30:45.2167869', '2026-08-20T02:30:45.2167869', NULL),
(7, 'WEL-2026-0007', 14, 4, 'Urgent travel assistance grant for attending national research symposium in Jaffna', 'Selected to present research paper at Jaffna University symposium. Requesting student travel allowance grant from welfare fund.', 'RESOLVED', 0, '2026-08-22T02:30:45.2167869', '2026-08-25T02:30:45.2167869', '2026-08-25T02:30:45.2167869'),
(8, 'WEL-2026-0008', 15, 4, 'Dean''s Emergency Student Relief Fund request following flood disruption in Gampaha', 'Family residence affected by heavy monsoon flooding in Kelani valley. Textbook and study materials damaged. Requesting emergency assistance package.', 'IN_PROGRESS', 1, '2026-08-24T02:30:45.2167869', '2026-08-28T02:30:45.2167869', NULL),
(9, 'WEL-2026-0009', 16, 4, 'Nutritional meal support & campus cafeteria subsidy voucher request', 'Applying for the subsidized student lunch meal token programme for this semester.', 'CLOSED', 0, '2026-08-26T02:30:45.2167869', '2026-08-29T02:30:45.2167869', '2026-08-29T02:30:45.2167869'),
(10, 'WEL-2026-0010', 17, NULL, 'Family bereavement leave and academic milestone postponement support', 'Sudden loss of immediate family member. Need compassionate leave endorsement and guidance on submitting exam deferral request.', 'NEW', 1, '2026-08-28T02:30:45.2167869', '2026-08-28T02:30:45.2167869', NULL),
(11, 'WEL-2026-0011', 18, 4, 'Visual disability screen-reader software license and lab accessibility request', 'Requesting university accessibility license for JAWS screen reading software on library lab workstations.', 'RESOLVED', 0, '2026-08-29T02:30:45.2167869', '2026-08-31T02:30:45.2167869', '2026-08-31T02:30:45.2167869'),
(12, 'WEL-2026-0012', 19, NULL, 'Confidential anxiety management consultation prior to final project viva', 'Seeking one-on-one session with student welfare counselor for public speaking stress and viva presentation anxiety.', 'NEW', 0, '2026-08-31T02:30:45.2167869', '2026-08-31T02:30:45.2167869', NULL),
(14, 'WEL-000013', 8, NULL, 'jirjir', 'uhsgiuerhgerugheruhsf9uh', 'NEW', 0, '2026-09-15T13:05:23.6185765', '2026-09-15T13:05:23.6185765', NULL),
(15, 'WEL-000014', 8, NULL, 'dewwf', 'deddeqfggr', 'NEW', 0, '2026-09-15T14:38:20.3876669', '2026-09-15T14:38:20.3876669', NULL),
(17, 'WEL-000016', 8, NULL, 'CRUD verify welfare', 'Verifying welfare CRUD end to end.', 'NEW', 1, '2026-09-15T16:30:25.7930703', '2026-09-15T16:30:26.9798701', NULL),
(22, 'WEL-000017', 18, 4, 'Requesting temporary fee deferment due to family financial hardship', 'My father recently lost his job and my family is currently unable to pay this semester''s tuition installment on time. I would like to request a temporary deferment of the payment deadline, or to know if I am eligible to apply for the university''s hardship bursary. I can provide supporting documents such as his termination letter if required. I do not want this to affect my registration for the upcoming semester.', 'IN_PROGRESS', 0, '2026-09-10T11:00:00', '2026-09-14T10:30:00', NULL);
