INSERT INTO announcements ([id], [title], [body], [created_by], [is_published], [start_date], [end_date], [created_at], [updated_at], [target_role], [priority]) VALUES
(1, 'Semester 2 Tuition Fee Installment Deadline Notice', 'Students paying semester tuition via installments are kindly requested to submit Commercial Bank / HNB deposit slips or online gateway payment receipts before the 15th to avoid late enrollment penalties.', 1, 1, '2026-08-10T16:38:34.1740392', '2026-08-17T16:38:34.1740392', '2026-08-12T16:38:34.1740392', '2026-08-12T16:38:34.1740392', NULL, 'NORMAL'),
(2, 'Annual Industry Placement & Tech Internship Fair 2026', 'Career Guidance Unit is hosting the Annual Tech Placement Day with leading partner employers (WSO2, IFS, Virtusa, 99x, London Stock Exchange Group). Pre-register on the student portal.', 1, 1, '2026-08-07T16:38:34.1740392', '2026-08-22T16:38:34.1740392', '2026-08-12T16:38:34.1740392', '2026-08-12T16:38:34.1740392', NULL, 'NORMAL'),
(3, 'Campus High-Speed Wi-Fi & Eduroam Scheduled Maintenance', 'Planned maintenance on the university campus core Wi-Fi and Eduroam network will occur this Saturday between 2:00 AM and 6:00 AM.', 1, 0, NULL, NULL, '2026-08-12T16:38:34.1740392', '2026-08-12T16:38:34.1740392', NULL, 'NORMAL'),
(4, 'End of Term Library 24/7 Hours', 'Updated: All floors open 24/7.', 1, 1, NULL, NULL, '2026-08-31T22:06:29.6899908', '2026-08-31T22:06:29.8331058', NULL, 'NORMAL'),
(27, 'Semester 2 Examination Timetable Published', 'The examination timetable for Semester 2, including repeat/re-sit papers, has been published on the student portal under Examinations. Please check your index number and exam hall allocation carefully. Any discrepancies in module registration or hall allocation must be reported to the Examinations & Assessments office within 5 working days by raising a ticket under the "Repeat Exam & Re-sits" or "Exam Timetable" category.', 1, 1, '2026-09-17T00:00:00', '2026-10-05T00:00:00', '2026-09-17T08:00:00', '2026-09-17T08:00:00', 'STUDENT', 'HIGH');
